/// <summary>
/// PricingAttribute of table <c>CustTable</c> field SalesPoolId.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, SalesPoolId))]
internal class GUPPricingAttributeCustTableSalesPoolId extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, SalesPoolId);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    Custtable    custTable;
    SalesPool    salesPool;

    while select SalesPoolId from custtable
        group by SalesPoolId
        join salesPool
        group by SalesPoolId, Name
        where custTable.SalesPoolId == salesPool.SalesPoolId
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(salesPool.SalesPoolId, salesPool.Name);
        ret.add(valueObject);
    }
    return ret;
}
